window.docContents[69].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Behavioral-Equivaleence--Simple-Examples":{"contents":"\n\ntheorem skip_left: ∀ c,\n  Com.equiv\n    (imp { skip; ~c })\n    c := by\n  sorry\n\n\nIs the syntax of Imp settled? I find this really unintuitive.\n\nProve that adding a skip after a command also results in an\nequivalent program.theorem skip_right : ∀ c,\n  Com.equiv\n    (imp { ~c; skip })\n    c := by\n  sorry\n\n\n\n\ntheorem if_true_simple: ∀ c₁ c₂,\n  Com.equiv\n    (imp {if (true) {~c₁} else {~c₂}})\n    c₁ := by\n  intro c₁ c₂ st st'\n  constructor <;> intro h\n  case mp =>\n    cases h with\n    | ifTrue => assumption\n    | ifFalse => contradiction\n  case mpr =>\n    apply Com.EvalR.ifTrue\n    · rfl\n    · assumption\n\n\n\n\nThe to_verso script seems to use \\[\\] blocks, but these seem to\ncause problems with the tilde. Currently skipping them and just using\nbackticks.\n\n\n\n\n\nif_true causes a naming conflict, I don't know with what.\n\ntheorem if_true_equiv: ∀ b c₁ c₂,\n  Bexp.equiv b (bexp {true}) ->\n  Com.equiv\n    (imp {if (~b) {~c₁} else {~c₂}})\n    c₁ := by\n  intro b c₁ c₂ hb st st'\n  constructor <;> intro h\n  case mp =>\n    cases h with\n    | ifTrue => assumption\n    | ifFalse hb' hc =>\n      unfold Bexp.equiv at hb; simp at hb\n      rw [hb] at hb'\n      contradiction\n  case mpr =>\n    apply Com.EvalR.ifTrue <;> try assumption\n    unfold Bexp.equiv at hb; dsimp at hb\n    apply hb\n\n\ntheorem if_false_equiv: ∀ b c₁ c₂,\n  Bexp.equiv b (bexp {false}) ->\n  Com.equiv\n    (imp {if (~b) {~c₁} else {~c₂}})\n    c₂ := by\n  sorry\n\n\nShow that we can swap the branches of an if if we also negate its\ncondition.theorem swap_if_branches : ∀ b c₁ c₂,\n  Com.equiv\n    (imp {if (~b) {~c₁} else {~c₂}})\n    (imp {if (¬ ~b) {~c₂} else {~c₁}}) := by\n  sorry\n\n\n\n\n\n\ntheorem while_false_equiv : ∀ b c,\n  Bexp.equiv b (bexp {false}) ->\n  Com.equiv\n    (imp {while (~b) {~c}})\n    (imp {skip}) := by\n  intro b c hb st st'\n  constructor <;> intro h\n  case mp =>\n    cases h with\n    | whileFalse => apply Com.EvalR.skip\n    | whileTrue hb' hc hloop =>\n      rw [hb] at hb'\n      simp at hb'\n  case mpr =>\n    cases h with\n    | skip =>\n      apply Com.EvalR.whileFalse\n      apply hb\n\n\nWrite an informal proof of while_false_equiv.\n\n\n\n\n\ntheorem while_true_nonterm : ∀ b c st st',\n  Bexp.equiv b (bexp {true}) ->\n  ¬ (st =[ while (~b) {~c} ]=> st') := by\n  sorry\n\n\nExplain what the lemma while_true_nonterm means in English.\n\nProve the following theorem. Hint: You'll want to use\nwhile_true_nonterm here.theorem while_true : ∀ b c,\n  Bexp.equiv b (bexp {true}) ->\n  Com.equiv\n    (imp {while (~b) {~c}})\n    (imp {while (true) {skip}}) := by\n  sorry\n\n\n\n\ntheorem loop_unrolling : ∀ b c,\n  Com.equiv\n    (imp {while (~b) {~c}})\n    (imp {\n      if (~b) {~c} else {skip};\n      while (~b) {~c}\n    }) := by\n  sorry\n\n\nLeaving out optional exercise seq_assoc for now.\n\n\n\nI am not able to use m[x] syntax here for some reason? I have to use function application and then do some weird manipulation.\nsyntax.\n\ntheorem identity_assignment : ∀ X,\n  Com.equiv\n    (imp {X := X})\n    (imp {skip}) := by\n  intro X st st'\n  constructor <;> intro hce\n  case mp =>\n    cases hce with\n    | asgn  h =>\n      dsimp at h\n      rw [← h, TotalMap.update_same]\n      apply Com.EvalR.skip\n\n  case mpr =>\n    cases hce with\n    | skip =>\n      suffices st =[ X := X ]=> X →ₜ st[X] ; st by\n        simp only [TotalMap.update_same] at this\n        exact this\n      apply Com.EvalR.asgn\n      simp\n\n\ntheorem assign_equiv : ∀ (X : Ident) (a : Aexp),\n  Aexp.equiv (aexp {X}) a ->\n  Com.equiv\n    (imp {skip})\n    (imp {X := ~a}) := by\n  sorry\n\n\nLeaving out optional exercise equiv_classes for now.\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Behavioral Equivaleence","header":"4.1.2. Simple Examples","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Behavioral-Equivaleence--Simple-Examples"}});